#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main() {
    time_t start_time;
    time_t end_time;

    // 1. Get the starting time using the return value (tloc = NULL)
    start_time = time(NULL);

    // Check for potential error (returns -1 on failure)
    if (start_time == ((time_t) -1)) {
        perror("time failed at start");
        return EXIT_FAILURE;
    }

    printf("Start Timestamp (seconds since Epoch): %ld\n", (long)start_time);

    // Simulate work
    sleep(2); 

    // 2. Get the ending time, storing the value both via return and tloc
    time(&end_time); 

    if (end_time == ((time_t) -1)) {
        perror("time failed at end");
        return EXIT_FAILURE;
    }

    printf("End Timestamp (seconds since Epoch): %ld\n", (long)end_time);
    printf("Elapsed time: %ld seconds\n", (long)(end_time - start_time));

    return EXIT_SUCCESS;
}
